* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: Arial, "Microsoft YaHei", sans-serif;
    background: #f3f8f1;
    color: #4d4642;
}

.container {
    max-width: 1200px;
    margin: auto;
    padding: 70px 50px;
}

/* ===== HEADER ===== */

header {
    margin-bottom: 55px;
}

.small-title {
    font-size: 16px;
    color: #9b918c;
    margin-bottom: 12px;
    letter-spacing: 2px;
}

h1 {
    font-size: 52px;
    font-weight: 600;
    margin-bottom: 15px;
}

.subtitle {
    font-size: 17px;
    color: #918782;
}


/* ===== CARDS ===== */

.learning-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 25px;
}

.learning-card {
    background: #fffdfb;
    border-radius: 25px;
    padding: 35px;
    min-height: 300px;

    display: flex;
    flex-direction: column;

    box-shadow: 0 8px 30px rgba(80, 70, 60, 0.06);

    transition: all 0.25s ease;
}

.learning-card:hover {
    transform: translateY(-7px);
    box-shadow: 0 15px 35px rgba(80, 70, 60, 0.10);
}


/* ===== ICON ===== */

.card-icon {
    font-size: 45px;
    margin-bottom: 30px;
}

.learning-card h2 {
    font-size: 25px;
    margin-bottom: 12px;
}

.learning-card p {
    font-size: 15px;
    line-height: 1.7;
    color: #918782;

    margin-bottom: auto;
}


/* ===== BUTTON ===== */

.learning-card button {
    margin-top: 30px;

    width: fit-content;

    border: none;
    background: #e8d8d0;
    color: #594e49;

    padding: 11px 18px;
    border-radius: 20px;

    font-size: 14px;

    cursor: pointer;

    transition: 0.2s;
}

.learning-card button:hover {
    background: #d9c5bb;
}


/* ===== MOBILE ===== */

@media (max-width: 800px) {

    .container {
        padding: 40px 25px;
    }

    h1 {
        font-size: 38px;
    }

    .learning-grid {
        grid-template-columns: 1fr;
    }

}.back-link {
    display: inline-block;
    margin-bottom: 20px;
    color: #888;
    text-decoration: none;
}

.hsk-level {
    margin-top: 30px;
}

.lesson-list {
    list-style: none;
    padding: 0;
}

.lesson-list li {
    margin-bottom: 10px;
}

.lesson-list li a {
    display: block;
    padding: 15px 20px;
    background: white;
    border-radius: 10px;
    text-decoration: none;
    color: #333;
}

.lesson-list li a:hover {
    background: #f0f0f0;
}.button {
    display: inline-block;
    background-color: #4a7856;
    color: white;
    padding: 10px 20px;
    border-radius: 20px;
    text-decoration: none;
    font-weight: 500;
    border: none;
    cursor: pointer;
}

.button:hover {
    background-color: #3d6448;
}

/* =====================================================================
   READING JOURNEY — "moon-gate garden" map
   6 cổng tương ứng 6 cấp HSK; mở cổng dẫn vào một con đường ngoằn ngoèo
   qua từng bài học (thay cho danh sách liệt kê).
   ===================================================================== */

:root {
    --jg-bg: #f3f8f1;
    --jg-ink: #4d4642;
    --jg-ink-soft: #8f8681;
    --jg-jade: #4a7856;
    --jg-jade-deep: #33553d;
    --jg-gold: #c99a52;
    --jg-gold-soft: #ecdcb8;
    --jg-paper: #fffdfb;
    --jg-lock: #b9b2ac;
}

.journey-body {
    background:
        radial-gradient(circle at 15% 8%, rgba(201, 154, 82, 0.10), transparent 40%),
        radial-gradient(circle at 85% 0%, rgba(74, 120, 86, 0.08), transparent 45%),
        var(--jg-bg);
}

.journey-container {
    max-width: 1100px;
    margin: auto;
    padding: 60px 30px 100px;
}

.journey-header {
    text-align: center;
    margin: 10px 0 55px;
}

.journey-eyebrow {
    font-family: 'Nunito', Arial, sans-serif;
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 3px;
    color: var(--jg-gold);
    text-transform: uppercase;
    margin-bottom: 10px;
}

.journey-title {
    font-family: 'Noto Serif SC', serif;
    font-size: 44px;
    font-weight: 700;
    color: var(--jg-jade-deep);
    margin-bottom: 12px;
}

.journey-sub {
    font-family: 'Nunito', Arial, sans-serif;
    font-size: 16px;
    color: var(--jg-ink-soft);
    max-width: 480px;
    margin: 0 auto;
}

/* ===== GATES GARDEN ===== */

.gates-garden {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 40px 30px;
    perspective: 1200px;
}

.gate {
    position: relative;
    border: none;
    background: none;
    cursor: pointer;
    padding: 10px 8px 0;
    font-family: inherit;
    display: flex;
    flex-direction: column;
    align-items: center;
}

/* all 6 gates sit in one even row — no staggering */

/* the arch is a pure "photo frame" — only the door scene lives inside it */
.gate-arch {
    position: relative;
    width: 100%;
    aspect-ratio: 3 / 5;
    border-radius: 50% 50% 8px 8px / 32% 32% 5px 5px;
    overflow: hidden;
    background-image: var(--door-img);
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    border: 5px solid var(--jg-gold);
    box-shadow:
        0 14px 30px rgba(51, 85, 63, 0.20),
        inset 0 0 0 3px rgba(255, 255, 255, 0.10);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.gate:hover .gate-arch {
    transform: translateY(-4px);
    box-shadow:
        0 20px 34px rgba(51, 85, 63, 0.26),
        inset 0 0 0 3px rgba(255, 255, 255, 0.14);
}

/* caption sits BELOW the arch, always legible, never hidden by the doors */
.gate-caption {
    margin-top: 12px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 3px;
}

.gate-era {
    font-family: 'Noto Serif SC', serif;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 1px;
    color: #1a1a1a;
}

.gate-plaque-row {
    display: flex;
    align-items: center;
    gap: 6px;
}

.gate-ornament {
    font-size: 16px;
    line-height: 1;
}

.gate-plaque {
    font-family: 'Noto Serif SC', serif;
    font-size: 21px;
    font-weight: 700;
    color: #111111;
    letter-spacing: 0.5px;
}

.gate-count {
    font-family: 'Nunito', Arial, sans-serif;
    font-size: 12px;
    color: #333333;
    letter-spacing: 0.3px;
}

/* the two door leaves — sized exactly to the arch's own box, meet at the centre */
.gate-leaf {
    position: absolute;
    top: 0;
    bottom: 0;
    width: 50%;
    background-image: var(--door-img);
    background-repeat: no-repeat;
    background-size: 200% 100%;
    transition: transform 0.65s cubic-bezier(.5,-0.2,.5,1.2);
    z-index: 2;
    backface-visibility: hidden;
    box-shadow: inset 0 0 0 1px rgba(0,0,0,0.18);
}

.gate-leaf.left {
    left: 0;
    background-position: left center;
    transform-origin: left center;
    border-right: 1px solid rgba(0,0,0,0.35);
}

.gate-leaf.right {
    right: 0;
    background-position: right center;
    transform-origin: right center;
    border-left: 1px solid rgba(0,0,0,0.35);
}

.gate.open .gate-leaf.left {
    transform: rotateY(-108deg);
}

.gate.open .gate-leaf.right {
    transform: rotateY(108deg);
}

/* scenery layer sits behind the leaves, revealed once the doors swing open */
.gate-scene {
    position: absolute;
    inset: 0;
    z-index: 1;
    overflow: hidden;
}

.gate:focus-visible .gate-arch {
    outline: 3px solid var(--jg-gold);
    outline-offset: 4px;
}

/* ===== JOURNEY / PATH VIEW ===== */

.journey-path {
    margin-top: 10px;
}

.path-back {
    display: inline-block;
    margin-bottom: 20px;
    background: none;
    border: none;
    font-family: 'Nunito', Arial, sans-serif;
    font-size: 15px;
    font-weight: 700;
    color: var(--jg-jade-deep);
    cursor: pointer;
    padding: 8px 4px;
}

.path-back:hover {
    text-decoration: underline;
}

.path-title {
    font-family: 'Noto Serif SC', serif;
    font-size: 32px;
    color: var(--jg-jade-deep);
    text-align: center;
    margin-bottom: 30px;
}

.path-canvas {
    position: relative;
    width: 100%;
    max-width: 620px;
    margin: 0 auto;
    min-height: 360px;
}

.path-line {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    overflow: visible;
}

.path-line path {
    stroke: var(--jg-gold);
    stroke-width: 1.4;
    stroke-linecap: round;
    stroke-dasharray: 4 3.5;
}

.path-node {
    position: absolute;
    transform: translate(-50%, -50%);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    text-decoration: none;
    width: 128px;
    opacity: 0;
    animation: nodePop 0.55s cubic-bezier(.34,1.56,.64,1) forwards;
}

@keyframes nodePop {
    from { opacity: 0; transform: translate(-50%, -50%) scale(0.4); }
    to   { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}

.node-stone {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: var(--jg-paper);
    border: 3px solid var(--jg-jade);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    box-shadow: 0 8px 18px rgba(51, 85, 63, 0.18);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.node-icon {
    font-size: 20px;
    line-height: 1;
}

.node-index {
    font-family: 'Nunito', Arial, sans-serif;
    font-size: 10px;
    font-weight: 700;
    color: var(--jg-jade-deep);
    margin-top: 2px;
}

.node-caption {
    font-family: 'Noto Serif SC', serif;
    font-size: 14px;
    color: var(--jg-ink);
    text-align: center;
    line-height: 1.4;
}

.node-caption em {
    font-family: 'Nunito', Arial, sans-serif;
    font-style: normal;
    font-size: 11px;
    color: var(--jg-ink-soft);
}

.path-node:hover .node-stone,
.path-node:focus-visible .node-stone {
    transform: translateY(-4px);
    box-shadow: 0 12px 22px rgba(51, 85, 63, 0.24);
}

.path-node.finish .node-stone {
    border-color: var(--jg-gold);
    background: linear-gradient(180deg, #fffdfb, var(--jg-gold-soft));
}

.path-node.locked {
    cursor: not-allowed;
}

.path-node.locked .node-stone {
    border-color: var(--jg-lock);
    background: #f1efec;
}

.path-node.locked .node-caption {
    color: var(--jg-ink-soft);
}

.path-node.locked:hover .node-stone {
    transform: none;
    box-shadow: 0 8px 18px rgba(51, 85, 63, 0.10);
}

/* ===== REDUCED MOTION ===== */

@media (prefers-reduced-motion: reduce) {
    .gate-arch, .gate-leaf, .node-stone { transition: none; }
    .path-node { animation: none; opacity: 1; }
}

/* ===== MOBILE ===== */

@media (max-width: 800px) {
    .gates-garden {
        grid-template-columns: repeat(2, 1fr);
        gap: 28px 18px;
    }
    .journey-title { font-size: 32px; }
    .path-canvas { max-width: 100%; }
    .node-stone { width: 54px; height: 54px; }
    .path-node { width: 100px; }
}

@media (max-width: 480px) {
    .gates-garden {
        grid-template-columns: repeat(2, 1fr);
        gap: 22px 12px;
    }
}



/* =====================================================================
   6 CỔNG — ẢNH THẬT NHÚNG TRỰC TIẾP TRONG CSS (base64)
   Không cần file ảnh riêng — mỗi ảnh được mã hoá thành chữ ngay tại đây.
   background-size: cover nên ảnh luôn phủ kín khung, không có khoảng
   trắng thừa.
   ===================================================================== */

.gate--ink {
    --door-img: url("data:image/jpeg;base64,");
}

.gate--tang {
    --door-img: url("data:image/jpeg;base64,");
}

.gate--garden {
    --door-img: url("data:image/jpeg;base64,");
}

.gate--deco {
    --door-img: url("data:image/jpeg;base64,");
}

.gate--neon {
    --door-img: url("data:image/jpeg;base64,");
}

.gate--future {
    --door-img: url("data:image/jpeg;base64,");
}

/* khung viền riêng từng thời đại */
.gate--ink .gate-arch { border-color: #2b2b2b; }
.gate--tang .gate-arch { border-color: #e6b64f; border-width: 6px; }
.gate--garden .gate-arch { border-color: #7fa583; }
.gate--deco .gate-arch { border-color: #d8b562; }

.gate--neon .gate-arch {
    border-color: #4fd1e8;
    box-shadow:
        0 14px 30px rgba(15, 20, 40, 0.30),
        0 0 18px rgba(79, 209, 232, 0.40),
        inset 0 0 0 3px rgba(255,255,255,0.06);
}
.gate--neon:hover .gate-arch,
.gate--neon:focus-visible .gate-arch {
    box-shadow:
        0 18px 34px rgba(15, 20, 40, 0.35),
        0 0 26px rgba(79, 209, 232, 0.55),
        inset 0 0 0 3px rgba(255,255,255,0.08);
}

.gate--future .gate-arch {
    border-image: linear-gradient(135deg, #9be8ff, #d6a9ff, #ffd9a0) 1;
    border-width: 4px;
    border-style: solid;
    box-shadow:
        0 14px 30px rgba(28, 16, 48, 0.35),
        0 0 20px rgba(214, 169, 255, 0.40);
}

@media (max-width: 480px) {
    .gate-era { font-size: 10px; }
}


/* =====================================================================
   SONGS — DANH SÁCH ĐĨA NHẠC
   ===================================================================== */

.songs-page,
.song-study-page {
    min-height: 100vh;
    background:
        radial-gradient(circle at 15% 10%, rgba(245, 194, 133, 0.20), transparent 32%),
        radial-gradient(circle at 90% 15%, rgba(132, 184, 158, 0.18), transparent 34%),
        #f3f8f1;
}

.songs-container,
.song-study-container {
    width: min(1120px, 92%);
    margin: 0 auto;
    padding: 54px 0 80px;
}

.songs-header {
    margin: 18px 0 34px;
}

.songs-eyebrow {
    margin-bottom: 8px;
    color: #7b987f;
    font-size: 13px;
    font-weight: 800;
    letter-spacing: 1.8px;
    text-transform: uppercase;
}

.songs-header h1 {
    margin-bottom: 8px;
    font-size: clamp(42px, 7vw, 72px);
}

.songs-header > p:last-child {
    color: #827a75;
    font-size: 17px;
}

.song-grid {
    display: grid;
    gap: 16px;
}

.song-card {
    display: grid;
    grid-template-columns: 104px minmax(0, 1fr) 50px;
    align-items: center;
    gap: 24px;
    padding: 18px 24px;
    border: 1px solid rgba(77, 70, 66, 0.06);
    border-radius: 24px;
    background: rgba(255, 255, 255, 0.86);
    box-shadow: 0 10px 28px rgba(74, 93, 76, 0.07);
    color: #4d4642;
    text-decoration: none;
    transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.song-card:not(.song-card--locked):hover {
    transform: translateY(-4px);
    box-shadow: 0 17px 36px rgba(74, 93, 76, 0.14);
}

.song-card-disc {
    position: relative;
    display: grid;
    flex: 0 0 92px;
    width: 92px;
    height: 92px;
    aspect-ratio: 1 / 1;
    place-items: center;
    overflow: hidden;
    border: 0;
    border-radius: 50%;
    background: transparent;
    box-shadow: 0 9px 22px rgba(79, 66, 55, 0.18);
}

.song-card-disc::after {
    display: none;
}

.song-card-disc img {
    position: absolute;
    inset: 0;
    display: block;
    min-width: 100%;
    max-width: none;
    width: 100%;
    height: 100%;
    border-radius: inherit;
    object-fit: cover;
    object-position: center 36%;
}

.song-card-hole {
    display: none;
}

.song-card-disc--placeholder {
    border-color: #ceddce;
    background: linear-gradient(135deg, #f6dbc2, #bdd9c5);
    color: white;
    font-family: "Microsoft YaHei", sans-serif;
    font-size: 34px;
    font-weight: 700;
}

.song-card-info {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 5px;
}

.song-card-info strong {
    font-size: 25px;
}

.song-card-info > span {
    color: #718777;
    font-size: 14px;
}

.song-card-info small {
    color: #9a918b;
    font-size: 13px;
}

.song-status {
    display: inline-flex;
    width: fit-content;
    align-items: center;
    gap: 6px;
    margin-top: 5px;
    padding: 5px 10px;
    border-radius: 999px;
    background: #f2f2f2;
    color: #777;
    font-size: 12px;
    font-style: normal;
    font-weight: 700;
}

.song-status::before {
    content: "";
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #d2d2d2;
}

.song-status[data-status="learning"]::before { background: #f3a847; }
.song-status[data-status="completed"]::before { background: #63b87b; }

.song-card-play {
    display: grid;
    width: 46px;
    height: 46px;
    place-items: center;
    border-radius: 50%;
    background: #789d83;
    color: white;
    font-size: 17px;
    box-shadow: 0 8px 18px rgba(82, 126, 94, 0.22);
}

.song-card--locked {
    opacity: 0.58;
}

.song-card--locked .song-card-play {
    background: #c4c6c3;
    box-shadow: none;
}


/* =====================================================================
   SONG STUDY — PLAYER, LỜI VÀ THẺ GHI CHÚ
   ===================================================================== */

.song-study-header {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 24px;
    margin: 14px 0 24px;
}

.song-study-header h1 {
    margin: 4px 0 6px;
    font-size: clamp(34px, 5vw, 58px);
}

.song-study-header p {
    color: #718777;
}

.song-study-layout {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 3fr) 1px minmax(190px, 1fr);
    gap: 22px;
    align-items: stretch;
}

.song-main-panel,
.song-note-sidebar {
    position: relative;
    z-index: 2;
}

.song-layout-divider {
    position: relative;
    z-index: 3;
    background: linear-gradient(transparent, #dce6dc 9%, #dce6dc 91%, transparent);
}

.song-connector-svg {
    position: absolute;
    inset: 0;
    z-index: 1;
    width: 100%;
    height: 100%;
    overflow: visible;
    pointer-events: none;
}

.song-player-card {
    position: sticky;
    top: 10px;
    z-index: 20;
    display: grid;
    grid-template-columns: 150px minmax(0, 1fr);
    gap: 26px;
    align-items: center;
    margin-bottom: 20px;
    padding: 22px;
    border-radius: 25px;
    background: rgba(255, 255, 255, 0.94);
    box-shadow: 0 12px 34px rgba(66, 88, 69, 0.11);
    backdrop-filter: blur(12px);
}

.song-record {
    position: relative;
    flex: 0 0 140px;
    width: 140px;
    height: 140px;
    aspect-ratio: 1 / 1;
    overflow: hidden;
    border: 0;
    border-radius: 50%;
    background: transparent;
    box-shadow: 0 12px 28px rgba(79, 66, 55, 0.2);
}

.song-record::after {
    display: none;
}

.song-record.playing {
    animation: songRecordSpin 5s linear infinite;
}

.song-record img {
    position: absolute;
    inset: 0;
    display: block;
    min-width: 100%;
    max-width: none;
    width: 100%;
    height: 100%;
    border-radius: inherit;
    object-fit: cover;
    object-position: center 36%;
}

.song-record-hole {
    display: none;
}

@keyframes songRecordSpin {
    to { transform: rotate(360deg); }
}

.song-player-info h2 {
    margin-bottom: 5px;
    font-size: 24px;
}

.song-player-info > p {
    margin-bottom: 17px;
    color: #8a807a;
    font-size: 13px;
}

.song-controls {
    display: flex;
    align-items: center;
    gap: 13px;
}

.song-play-button {
    flex: 0 0 auto;
    width: 44px;
    height: 44px;
    border: none;
    border-radius: 50%;
    background: #6f987b;
    color: white;
    cursor: pointer;
    font-size: 17px;
}

.song-time {
    flex: 0 0 auto;
    min-width: 84px;
    color: #766e69;
    font-size: 12px;
}

.song-progress {
    min-width: 0;
    flex: 1;
    accent-color: #6f987b;
    cursor: pointer;
}

.song-lyrics-card {
    padding: 34px 28px;
    border-radius: 25px;
    background: rgba(255, 255, 255, 0.88);
    box-shadow: 0 10px 30px rgba(66, 88, 69, 0.08);
}

.song-lyrics-card h3 {
    margin-bottom: 6px;
    font-size: 20px;
}

.song-lyrics-help {
    margin-bottom: 20px;
    color: #9a918b;
    font-size: 12px;
}

.song-lyrics-scroll {
    height: 520px;
    overflow-y: auto;
    padding: 190px 14px;
    scroll-behavior: smooth;
}

.lyric-line {
    position: relative;
    margin: 10px 0;
    padding: 13px 16px;
    border-radius: 15px;
    color: #a39d98;
    cursor: pointer;
    font-size: 20px;
    line-height: 1.65;
    transform-origin: left center;
    transition: color 0.3s ease, background 0.3s ease, transform 0.3s ease, opacity 0.3s ease;
}

.lyric-line.active {
    z-index: 3;
    background: #edf5ed;
    color: #3f6148;
    font-weight: 700;
    transform: scale(1.045);
    box-shadow: 0 8px 22px rgba(73, 112, 82, 0.10);
}

.lyric-line.past {
    color: #827b77;
    opacity: 1;
    visibility: visible;
    display: block;
}

.song-word {
    border-radius: 5px;
    cursor: pointer;
    transition: background 0.2s ease;
}

.song-word:hover {
    background: #dcebdc;
}

.song-word.highlight-green { background: #b8e2c4; }
.song-word.highlight-blue { background: #b9d9f4; }
.song-word.highlight-yellow { background: #f4e6a3; }
.song-word.highlight-purple { background: #dbcaf0; }
.song-word.highlight-orange { background: #ffd2a8; }
.song-word.highlight-gray { background: #d9dde1; }
.song-word.is-underlined {
    text-decoration: underline;
    text-decoration-thickness: 1px;
    text-underline-offset: 3px;
}

.song-note-sidebar {
    min-height: 760px;
    padding: 10px 0 40px;
}

.song-note-sidebar h3 {
    margin-bottom: 13px;
    color: #6f7e71;
    font-size: 15px;
}

.song-note-empty {
    padding: 18px 10px;
    color: #aaa39e;
    font-size: 13px;
}

.song-note-card {
    position: relative;
    z-index: 4;
    margin-bottom: 10px;
    padding: 12px 32px 12px 14px;
    border: 1px solid #e0eae0;
    border-radius: 13px;
    background: rgba(255, 255, 255, 0.96);
    box-shadow: 0 6px 15px rgba(73, 101, 78, 0.07);
    transition: transform 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease;
}

.song-note-card.active-line-note {
    z-index: 7;
    transform: scale(1.055);
    border-color: #81ac8b;
    box-shadow: 0 12px 26px rgba(73, 112, 82, 0.20);
}

.song-note-card strong {
    display: block;
    margin-bottom: 4px;
    font-size: 18px;
}

.song-note-card p {
    color: #7e7772;
    font-size: 12px;
    line-height: 1.5;
}

.song-note-remove {
    position: absolute;
    top: 8px;
    right: 8px;
    width: 22px;
    height: 22px;
    border: none;
    border-radius: 50%;
    background: #f5e2e2;
    color: #9a6666;
    cursor: pointer;
}

.song-word-popup {
    position: fixed;
    top: 50%;
    left: 50%;
    z-index: 1000;
    display: none;
    width: min(360px, 90vw);
    transform: translate(-50%, -50%);
    padding: 28px;
    border-radius: 22px;
    background: white;
    box-shadow: 0 20px 60px rgba(42, 50, 43, 0.28);
    text-align: center;
}

.song-word-popup.show { display: block; }
.song-word-popup h2 { margin-bottom: 5px; font-size: 38px; }
.song-word-popup p { margin: 6px 0; }
.song-word-popup .popup-pinyin { color: #64866d; font-size: 18px; }
.song-word-popup .popup-meta { color: #8d8580; font-size: 13px; }

.song-popup-close {
    position: absolute;
    top: 10px;
    right: 13px;
    border: none;
    background: none;
    color: #8c8580;
    cursor: pointer;
    font-size: 24px;
}

.song-popup-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 9px;
    margin-top: 18px;
}

.song-popup-actions button {
    padding: 10px 12px;
    border: none;
    border-radius: 12px;
    background: #7da487;
    color: white;
    cursor: pointer;
    font-weight: 700;
}

.song-popup-actions button.active { background: #4f7f5d; }

.song-highlight-tools {
    display: flex;
    justify-content: center;
    gap: 9px;
    margin-top: 14px;
}

.song-color-button {
    width: 28px;
    height: 28px;
    border: 3px solid white;
    border-radius: 50%;
    box-shadow: 0 0 0 1px #ccc;
    cursor: pointer;
}

.song-color-button.green { background: #8fc7a5; }
.song-color-button.blue { background: #82b7e8; }
.song-color-button.yellow { background: #f4d66d; }
.song-color-button.purple { background: #ad8ed6; }
.song-color-button.orange { background: #ffd2a8; }
.song-color-button.gray { background: #aeb5bd; }

.song-underline-button {
    width: 30px;
    height: 30px;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    font-weight: 700;
    text-decoration: underline;
}

.song-saved-card {
    margin-top: 20px;
    padding: 18px 22px;
    border-radius: 20px;
    background: rgba(255, 255, 255, 0.88);
}

.song-saved-card h3 { margin-bottom: 10px; font-size: 16px; }
.song-saved-chip {
    display: inline-flex;
    margin: 4px;
    padding: 7px 10px;
    border-radius: 999px;
    background: #e9f2e9;
    color: #56705d;
    font-size: 13px;
}

@media (max-width: 760px) {
    .songs-container,
    .song-study-container {
        width: 96%;
        padding-top: 28px;
    }

    .song-card {
        grid-template-columns: 72px minmax(0, 1fr) 40px;
        gap: 13px;
        padding: 13px;
    }

    .song-card-disc { flex-basis: 68px; width: 68px; height: 68px; }
    .song-card-info strong { font-size: 18px; }
    .song-card-play { width: 38px; height: 38px; }

    .song-study-layout {
    grid-template-columns: minmax(0, 1fr);
    gap: 16px;
}

.song-layout-divider {
    display: none;
}

    .song-study-header h1 { font-size: 28px; }
    .song-study-header { align-items: flex-start; flex-direction: column; }

    .song-player-card {
        grid-template-columns: 76px minmax(0, 1fr);
        gap: 10px;
        padding: 10px;
        border-radius: 16px;
    }

    .song-record { flex-basis: 72px; width: 72px; height: 72px; }
    .song-player-info h2 { font-size: 15px; }
    .song-player-info > p { margin-bottom: 8px; font-size: 10px; }
    .song-play-button { width: 34px; height: 34px; }
    .song-time { min-width: 65px; font-size: 9px; }

    .song-lyrics-card { padding: 15px 9px; border-radius: 16px; }
    .song-lyrics-scroll { height: 470px; padding: 175px 4px; }
    .lyric-line { padding: 9px 7px; font-size: 15px; line-height: 1.5; }
    .lyric-line.active { transform: scale(1.025); }

    .song-note-sidebar { min-height: 650px; padding-top: 4px; }
    .song-note-sidebar h3 { font-size: 11px; }
    .song-note-empty { padding: 8px 2px; font-size: 9px; }
    .song-note-card { padding: 8px 20px 8px 7px; border-radius: 9px; }
    .song-note-card strong { font-size: 13px; }
    .song-note-card p { font-size: 9px; }
    .song-note-card.active-line-note { transform: scale(1.035); }
}

@media (prefers-reduced-motion: reduce) {
    .song-record.playing { animation: none; }
    .lyric-line,
    .song-note-card { transition: none; }
}
